require_once __DIR__.'/includes/functions.php';if(current_user())redirect('index.php');$page_title='Create account';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');
if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Enter your name (2–100 characters).';
if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';
if(strlen($pass)<8)$errors[]='Password must be at least 8 characters.';
if(!$errors){try{$s=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];flash('success','Welcome to StyleCart!');redirect('index.php');}catch(PDOException $ex){$errors[]='An account with this email may already exist.';}}
}
include __DIR__.'/includes/header.php'; ?><div class="form-panel"><span class="eyebrow">Join the style club</span><h1 class="section-title mt-2">Create account</h1><p class="muted">A better everyday wardrobe starts here.</p><?php foreach($errors as $er): ?><div class="alert alert-danger"><?= e($er) ?></div><?php endforeach; ?><form method="post"><?= csrf_field() ?><label class="form-label">Full name</label><input class="form-control mb-3" name="name" required maxlength="100" value="<?= e($_POST['name']??'') ?>"><label class="form-label">Email address</label><input class="form-control mb-3" type="email" name="email" required value="<?= e($_POST['email']??'') ?>"><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" required minlength="8" autocomplete="new-password"><button class="btn btn-dark w-100">Create account</button></form><p class="mt-3 mb-0">Already have an account? <a class="text-decoration-underline" href="<?= e(url('login.php')) ?>">Sign in</a></p></div><?php include __DIR__.'/includes/footer.php'; ?>
